-  });
-
-  it('RED ks1868 R3 removeConnection: a revoked Proxy still emits connectionRemoved and logs a constant reason', async () => {
-    h.toThrow = revokedProxy();
-    expect(await removeOutcome()).toEqual({ threw: false, removed: 1 });
