+ * Wednesday (ANSWER 2026-11-06 05:40:48Z, option A, tier 1): the Redis cache section of services/shared (@secuura/service-utils) imported by nothing is
+ * deleted: src/cache/ (5 files), src/security/redis-security-store.ts (it imports ../cache/redis-client, so it cannot outlive the cache), their two
+ * re-exports, and the six KS-1868 tests that pinned them. types/ stays: services/billing vendors it (Dockerfile:47 and a relative import).
+ *
+ * Source-text and file-system cells, so nothing here needs a Redis, a port or a build.
+ *   RED      fails against develop (the section is still there), passes once it is deleted.
+ *   CONTROL  passes on both, and can fail: it pins what must NOT be deleted.
+ */
+import { describe, it, expect } from 'vitest';
+import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
+import { join, resolve } from 'node:path';
+
+const PKG = resolve(__dirname, '..', '..'); // services/shared
+const SRC = join(PKG, 'src');
+const BILLING_DOCKERFILE = resolve(PKG, '..', 'billing', 'Dockerfile');
+
+/** Every non-test .ts file under src/ (the cells below read these as text). */
+function sources(dir: string): string[] {
+  if (!existsSync(dir)) return [];
+  return readdirSync(dir).flatMap((name) => {
+    const p = join(dir, name);
+    if (statSync(p).isDirectory()) return name === '__tests__' ? [] : sources(p);
+    return p.endsWith('.ts') ? [p] : [];
+  });
+}
+/** The text of a file without whole-line comments (the "was ..." comments that explain a deletion may name what was deleted). */
+const code = (p: string) => readFileSync(p, 'utf8').split('\n').filter((l) => !/^\s*(\/\/|\*|\/\*)/.test(l)).join('\n');
+
+describe('KS-657 the unused Redis cache section of services/shared is deleted', () => {
+  it('RED G1 src/cache/ does not exist', () => {
+    expect(existsSync(join(SRC, 'cache'))).toBe(false);
+  });
+
+  it('RED G2 src/security/redis-security-store.ts does not exist', () => {
+    expect(existsSync(join(SRC, 'security', 'redis-security-store.ts'))).toBe(false);
+  });
+
+  it('RED G3 neither index re-exports the deleted code', () => {
+    expect(code(join(SRC, 'index.ts'))).not.toMatch(/['"]\.\/cache['"]/);
+    expect(code(join(SRC, 'security', 'index.ts'))).not.toMatch(/redis-security-store|RedisBruteForceStore|RedisCSRFStore|RedisRateLimitStore/);
+  });
+
+  it('RED G4 no remaining source imports or re-exports a path into a cache folder, the redis client, or the redis security store', () => {
+    const offenders = sources(SRC)
+      .filter((f) => /from\s+['"][^'"]*(\/cache\b|redis-client|redis-security-store)[^'"]*['"]/.test(code(f)))
+      .map((f) => f.slice(PKG.length + 1));
+    expect(offenders).toEqual([]);
+  });
+
+  it('control G4b the import scan can fail: it flags a planted re-export and a planted import, and passes the kept ones', () => {
+    const hit = (s: string) => /from\s+['"][^'"]*(\/cache\b|redis-client|redis-security-store)[^'"]*['"]/.test(s);
+    expect(hit("export * from './cache';")).toBe(true);
+    expect(hit("import { redisClient } from '../cache/redis-client';")).toBe(true);
+    expect(hit("} from './redis-security-store';")).toBe(true);
+    expect(hit("export * from './security';")).toBe(false);
+    expect(hit("import { logger } from '../utils/logger';")).toBe(false);
+  });
+
+  it('control G5 what is kept is still there: the other security files, the logger, both indexes', () => {
+    for (const f of ['index.ts', 'security/index.ts', 'security/audit.ts', 'security/headers.ts', 'security/rate-limiter.ts', 'security/validation.ts', 'utils/logger.ts']) {
+      expect({ f, exists: existsSync(join(SRC, f)) }).toEqual({ f, exists: true });
+    }
+  });
+
+  it('control G6 the types billing vendors are kept: types/svs-types.ts exists and billing still copies services/shared/types/', () => {
+    expect(existsSync(join(PKG, 'types', 'svs-types.ts'))).toBe(true);
+    expect(readFileSync(BILLING_DOCKERFILE, 'utf8')).toContain('COPY services/shared/types/ /app/vendor/shared/types/');
+  });
+});

