-      return { count, resetAt };
-    } catch (error) {
-      let reason: string;
-      try {
-        reason = String(error);
-      } catch {
-        reason = 'unreadable thrown value';
-      }
-      logger.error('RedisRateLimitStore error incrementing', { error: reason });
